import { UUID, Timestamps } from './common';
import { TicketStatus, TicketPriority } from './Ticket';
import { TaskStatus, TaskPriority } from './Task';

/**
 * History Models
 * Types and interfaces for work history and activity tracking
 */

export enum HistoryItemType {
  Ticket = 'ticket',
  Task = 'task',
}

export enum HistoryActionType {
  Created = 'created',
  Assigned = 'assigned',
  Started = 'started',
  Completed = 'completed',
  Resolved = 'resolved',
  Closed = 'closed',
  Cancelled = 'cancelled',
  Reopened = 'reopened',
  PriorityChanged = 'priority_changed',
  StatusChanged = 'status_changed',
}

export interface HistoryItem extends Timestamps {
  id: UUID;
  type: HistoryItemType;
  entityId: UUID;
  entityCode: string;
  entityTitle: string;
  actionType: HistoryActionType;
  actionDescription: string;
  priority: TicketPriority | TaskPriority;
  status: string;
  completedAt?: string;
  timeSpent?: number; // in hours
  estimatedTime?: number; // in hours
  rating?: number; // 1-5
  slaStatus?: 'on_time' | 'warning' | 'breached';
  slaBreachMinutes?: number;
  metadata?: HistoryItemMetadata;
}

export interface HistoryItemMetadata {
  department?: string;
  category?: string;
  oldPriority?: TicketPriority | TaskPriority;
  newPriority?: TicketPriority | TaskPriority;
  oldStatus?: TicketStatus | TaskStatus;
  newStatus?: TicketStatus | TaskStatus;
  [key: string]: any;
}

export interface HistoryStats {
  totalCompleted: number;
  completedThisMonth: number;
  completedThisWeek: number;
  totalTimeSpent: number; // in hours
  averageRating: number;
  onTimePercentage: number;
  slaBreaches: number;
}

export interface HistoryFilters {
  search?: string;
  dateRange?: {
    from: Date;
    to: Date;
  };
  type?: HistoryItemType;
  priority?: TicketPriority | TaskPriority;
  actionType?: HistoryActionType;
}

export interface HistoryGrouping {
  date: string; // YYYY-MM-DD
  displayDate: string; // "Hôm nay - 25/03/2026"
  items: HistoryItem[];
}

export interface HistoryExportOptions {
  format: 'pdf' | 'csv';
  dateRange?: {
    from: Date;
    to: Date;
  };
  includeStats?: boolean;
}

/**
 * Get icon for history action type
 */
export const getHistoryActionIcon = (actionType: HistoryActionType): string => {
  switch (actionType) {
    case HistoryActionType.Created:
      return 'fas fa-plus-circle';
    case HistoryActionType.Assigned:
      return 'fas fa-user-plus';
    case HistoryActionType.Started:
      return 'fas fa-play-circle';
    case HistoryActionType.Completed:
    case HistoryActionType.Resolved:
      return 'fas fa-check-circle';
    case HistoryActionType.Closed:
      return 'fas fa-lock';
    case HistoryActionType.Cancelled:
      return 'fas fa-times-circle';
    case HistoryActionType.Reopened:
      return 'fas fa-redo';
    case HistoryActionType.PriorityChanged:
      return 'fas fa-exclamation-triangle';
    case HistoryActionType.StatusChanged:
      return 'fas fa-exchange-alt';
    default:
      return 'fas fa-info-circle';
  }
};

/**
 * Get color for history action type
 */
export const getHistoryActionColor = (actionType: HistoryActionType): string => {
  switch (actionType) {
    case HistoryActionType.Created:
    case HistoryActionType.Started:
      return 'var(--info-color)';
    case HistoryActionType.Assigned:
      return 'var(--primary-color)';
    case HistoryActionType.Completed:
    case HistoryActionType.Resolved:
    case HistoryActionType.Closed:
      return 'var(--success-color)';
    case HistoryActionType.Cancelled:
      return 'var(--danger-color)';
    case HistoryActionType.Reopened:
      return 'var(--warning-color)';
    case HistoryActionType.PriorityChanged:
      return 'var(--warning-color)';
    case HistoryActionType.StatusChanged:
      return 'var(--primary-color)';
    default:
      return 'var(--gray-500)';
  }
};

/**
 * Get badge variant for priority
 */
export const getPriorityBadgeVariant = (
  priority: TicketPriority | TaskPriority
): string => {
  switch (priority) {
    case 'critical':
      return 'badge-danger';
    case 'high':
      return 'badge-warning';
    case 'medium':
      return 'badge-info';
    case 'low':
      return 'badge-secondary';
    default:
      return 'badge-secondary';
  }
};

/**
 * Get display text for priority
 */
export const getPriorityText = (priority: TicketPriority | TaskPriority): string => {
  switch (priority) {
    case 'critical':
      return 'Khẩn cấp';
    case 'high':
      return 'Cao';
    case 'medium':
      return 'Trung bình';
    case 'low':
      return 'Thấp';
    default:
      return priority;
  }
};

/**
 * Format time spent
 */
export const formatTimeSpent = (hours?: number): string => {
  if (!hours) return '-';
  if (hours < 1) {
    return `${Math.round(hours * 60)} phút`;
  }
  return `${hours.toFixed(1)}h`;
};

/**
 * Group history items by date
 */
export const groupHistoryByDate = (items: HistoryItem[]): HistoryGrouping[] => {
  const groups: { [key: string]: HistoryItem[] } = {};
  
  items.forEach(item => {
    const date = new Date(item.completedAt || item.createdAt);
    const dateKey = date.toISOString().split('T')[0];
    
    if (!groups[dateKey]) {
      groups[dateKey] = [];
    }
    groups[dateKey].push(item);
  });

  const today = new Date();
  const yesterday = new Date(today);
  yesterday.setDate(yesterday.getDate() - 1);
  
  const todayKey = today.toISOString().split('T')[0];
  const yesterdayKey = yesterday.toISOString().split('T')[0];

  return Object.keys(groups)
    .sort((a, b) => b.localeCompare(a)) // Sort descending
    .map(dateKey => {
      const date = new Date(dateKey);
      let displayDate = '';
      
      if (dateKey === todayKey) {
        displayDate = `Hôm nay - ${date.getDate()}/${date.getMonth() + 1}/${date.getFullYear()}`;
      } else if (dateKey === yesterdayKey) {
        displayDate = `Hôm qua - ${date.getDate()}/${date.getMonth() + 1}/${date.getFullYear()}`;
      } else {
        displayDate = `${date.getDate()}/${date.getMonth() + 1}/${date.getFullYear()}`;
      }

      return {
        date: dateKey,
        displayDate,
        items: groups[dateKey].sort((a, b) => {
          const timeA = new Date(a.completedAt || a.createdAt).getTime();
          const timeB = new Date(b.completedAt || b.createdAt).getTime();
          return timeB - timeA; // Sort descending within each day
        }),
      };
    });
};
