import React, { useState } from 'react';
import { Slideout } from '../../../components/common/Slideout';
import { Ticket, TicketHelper } from '../../../models/Ticket';
import { UUID } from '../../../models/common';
import {
  UserMultiSearchInput,
  SelectedUser,
} from '../../../components/common/UserSearchInput/UserMultiSearchInput';
import { useAppToast } from '../../../hooks/useAppToast';
import styles from './SupportAssignmentModal.module.css';

interface SupportAssignmentModalProps {
  ticket: Ticket;
  isOpen: boolean;
  onClose: () => void;
  onSubmit: (helpers: Omit<TicketHelper, 'id' | 'assignedAt' | 'assignedById' | 'assignedByName'>[]) => Promise<void>;
}

const SupportAssignmentModal: React.FC<SupportAssignmentModalProps> = ({
  ticket,
  isOpen,
  onClose,
  onSubmit,
}) => {
  const toast = useAppToast();
  const [selectedUsers, setSelectedUsers] = useState<SelectedUser[]>([]);
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    if (selectedUsers.length === 0) {
      setError('Vui lòng chọn ít nhất 1 người hỗ trợ');
      return;
    }

    setSubmitting(true);
    setError(null);

    try {
      const helpers = selectedUsers.map((u) => ({
        userId: u.userId as UUID,
        userName: u.fullName,
      }));

      await onSubmit(helpers);
      toast.success(`Đã phân công ${selectedUsers.length} người hỗ trợ thành công`);
      handleClose();
    } catch (err: unknown) {
      toast.fromError(err, 'Có lỗi xảy ra khi phân công người hỗ trợ. Vui lòng thử lại.');
      setError('Có lỗi xảy ra khi phân công người hỗ trợ. Vui lòng thử lại.');
    } finally {
      setSubmitting(false);
    }
  };

  const handleClose = () => {
    if (!submitting) {
      setSelectedUsers([]);
      setError(null);
      onClose();
    }
  };

  if (!isOpen) return null;

  const handleConfirmAssign = () => {
    handleSubmit(new Event('submit') as any);
  };

  return (
    <Slideout 
      isOpen={isOpen} 
      onClose={handleClose} 
      title="Phân Công Người Hỗ Trợ"
      width="700px"
      footer={{
        leftLabel: 'Hủy',
        leftAction: handleClose,
        leftDisabled: submitting,
        rightLabel: submitting 
          ? 'Đang phân công...' 
          : `Phân Công (${selectedUsers.length} người)`,
        rightAction: handleConfirmAssign,
        rightDisabled: submitting || selectedUsers.length === 0,
      }}
    >
      <form onSubmit={handleSubmit} className={styles.form}>
        {/* Ticket Info */}
        <div className={styles.ticketInfo}>
          <div className={styles.infoHeader}>
            <i className="fas fa-ticket-alt"></i>
            <h4>Thông Tin Ticket</h4>
          </div>
          <div className={styles.infoGrid}>
            <div className={styles.infoItem}>
              <span className={styles.infoLabel}>Mã Ticket:</span>
              <span className={styles.infoValue}>{ticket.idCode || ticket.id}</span>
            </div>
            <div className={styles.infoItem}>
              <span className={styles.infoLabel}>Tiêu đề:</span>
              <span className={styles.infoValue}>{ticket.title}</span>
            </div>
            <div className={styles.infoItem}>
              <span className={styles.infoLabel}>Người xử lý chính:</span>
              <span className={styles.infoValue}>{ticket.assigneeName || 'Chưa giao'}</span>
            </div>
            <div className={styles.infoItem}>
              <span className={styles.infoLabel}>Phòng ban:</span>
              <span className={styles.infoValue}>{ticket.departmentName}</span>
            </div>
          </div>
        </div>

        {/* Help Request Info */}
        {ticket.helpRequestDescription && (
          <div className={styles.helpRequest}>
            <div className={styles.helpRequestHeader}>
              <i className="fas fa-hands-helping"></i>
              <h4>Yêu Cầu Hỗ Trợ</h4>
            </div>
            <p className={styles.helpRequestDescription}>{ticket.helpRequestDescription}</p>
            {ticket.helpRequestedAt && (
              <p className={styles.helpRequestTime}>
                <i className="fas fa-clock"></i>
                Yêu cầu lúc: {new Date(ticket.helpRequestedAt).toLocaleString('vi-VN')}
              </p>
            )}
          </div>
        )}

        {/* User Multi-Select */}
        <UserMultiSearchInput
          value={selectedUsers}
          onChange={(users) => { setSelectedUsers(users); setError(null); }}
          excludeUserIds={ticket.assigneeId ? [ticket.assigneeId] : []}
          label="Chọn Người Hỗ Trợ"
          placeholder="Nhập mã hoặc tên để tìm..."
          showDepartmentFilter
          inline
          required
          error={error ?? undefined}
        />

        {/* Summary */}
        {selectedUsers.length > 0 && (
          <div className={styles.summary}>
            <i className="fas fa-info-circle"></i>
            <p>
              Bạn đang phân công <strong>{selectedUsers.length}</strong> người để hỗ trợ ticket
              này. Họ sẽ nhận được thông báo ngay lập tức.
            </p>
          </div>
        )}
      </form>
    </Slideout>
  );
};

export default SupportAssignmentModal;
