import React from 'react';
import { Card } from '../../common/Card';
import { ScheduleItem } from '../../../models/Dashboard';
import styles from './TodaysDeadlines.module.css';

export interface TodaysDeadlinesProps {
  scheduleItems: ScheduleItem[];
  date?: string;
}

export const TodaysDeadlines: React.FC<TodaysDeadlinesProps> = ({
  scheduleItems,
  date = '25 Tháng 3, 2026',
}) => {
  const getPriorityClass = (priority: string): string => {
    switch (priority) {
      case 'critical':
        return 'danger';
      case 'high':
        return 'warning';
      case 'medium':
        return 'success';
      default:
        return 'primary';
    }
  };

  const getPriorityLabel = (priority: string): string => {
    switch (priority) {
      case 'critical':
        return 'CRITICAL';
      case 'high':
        return 'HIGH';
      case 'medium':
        return 'MEDIUM';
      default:
        return 'LOW';
    }
  };

  return (
    <Card className={styles.todaysDeadlines}>
      <div className={styles.header}>
        <h3 className={styles.title}>
          <i className="fas fa-calendar-day"></i> Lịch Hôm Nay - {date}
        </h3>
      </div>
      <div className={styles.scheduleGrid}>
        {scheduleItems.length === 0 ? (
          <div className={styles.emptyState}>
            <i className="fas fa-calendar-check" />
            <p>Không có deadline nào hôm nay — Tốt lắm!</p>
          </div>
        ) : (
          scheduleItems.map((item) => {
            const priorityClass = getPriorityClass(item.priority);
            const priorityLabel = getPriorityLabel(item.priority);
            return (
              <div key={item.id} className={`${styles.scheduleItem} ${styles[priorityClass]}`}>
                <div className={styles.scheduleHeader}>
                  <span className={styles.time}>{item.time}</span>
                  <span className={styles.priority}>{priorityLabel}</span>
                </div>
                <div className={styles.scheduleTitle}>
                  {item.code}: {item.title}
                </div>
                <div className={styles.scheduleSubtitle}>
                  {item.subtitle}
                  {item.deadline && ` - ${item.deadline}`}
                </div>
              </div>
            );
          })
        )}
      </div>
    </Card>
  );
};
