/**
 * Notification service — TypeScript type definitions.
 *
 * Mirrors the C# DTOs in WebApp.BFF/DTOs/Notifications/NotificationDtos.cs
 */

// ── Notification type constants ───────────────────────────────────────────────

export const NotificationType = {
  TICKET_ASSIGNED:  'TICKET_ASSIGNED',
  TASK_ASSIGNED:    'TASK_ASSIGNED',
  NEW_MESSAGE:      'NEW_MESSAGE',
  STATUS_CHANGED:   'STATUS_CHANGED',
  APPROVAL_NEEDED:  'APPROVAL_NEEDED',
  SLA_WARNING:      'SLA_WARNING',
  SLA_BREACH:       'SLA_BREACH',

  // New channels
  TICKET_SUPPORT_ASSIGNED:    'TICKET_SUPPORT_ASSIGNED',
  TASK_COLLABORATOR_ASSIGNED: 'TASK_COLLABORATOR_ASSIGNED',
  TASK_REASSIGNED:            'TASK_REASSIGNED',

  // Placeholders (future — department-based notifications)
  TICKET_CREATED_FOR_DEPT:    'TICKET_CREATED_FOR_DEPT',
  TASK_ASSIGNED_TO_DEPT:      'TASK_ASSIGNED_TO_DEPT',
} as const;

export type NotificationTypeValue = (typeof NotificationType)[keyof typeof NotificationType];

// ── Notification priority constants ──────────────────────────────────────────

export const NotificationPriority = {
  LOW:      'LOW',
  MEDIUM:   'MEDIUM',
  HIGH:     'HIGH',
  CRITICAL: 'CRITICAL',
} as const;

export type NotificationPriorityValue = (typeof NotificationPriority)[keyof typeof NotificationPriority];

// ── Core DTO ─────────────────────────────────────────────────────────────────

export interface NotificationDto {
  id:         string;
  type:       NotificationTypeValue;
  priority:   NotificationPriorityValue;
  title:      string;
  message:    string;
  actionUrl:  string;
  entityType: string | null;
  entityId:   string | null;
  isRead:     boolean;
  readAt:     string | null;
  createdAt:  string;
}

// ── Paginated result ──────────────────────────────────────────────────────────

export interface NotificationPagedResult {
  items:       NotificationDto[];
  totalCount:  number;
  unreadCount: number;
  page:        number;
  pageSize:    number;
}

// ── Unread count ──────────────────────────────────────────────────────────────

export interface UnreadCountDto {
  count: number;
}
