/**
 * HistoryTimeline Component
 * Timeline display of grouped history items
 */

import React from 'react';
import { HistoryGrouping } from '../../../models/History';
import { ActivityCard } from '../ActivityCard';
import styles from './HistoryTimeline.module.css';

interface HistoryTimelineProps {
  groupedHistory: HistoryGrouping[];
  loading?: boolean;
}

export const HistoryTimeline: React.FC<HistoryTimelineProps> = ({ groupedHistory, loading }) => {
  if (loading) {
    return (
      <div className={styles.loading}>
        <i className="fas fa-spinner fa-spin"></i>
        <p>Đang tải...</p>
      </div>
    );
  }

  return (
    <div className={styles.timelineCard}>
      <h3 className={styles.timelineTitle}>
        <i className="fas fa-timeline"></i>
        Timeline công việc
      </h3>

      <div className={styles.timeline}>
        {groupedHistory.map((group) => (
          <div key={group.date} className={styles.timelineSection}>
            <div className={styles.timelineDate}>{group.displayDate}</div>

            <div className={styles.timelineItems}>
              {group.items.map((item) => (
                <div key={item.id} className={styles.timelineItem}>
                  <div
                    className={styles.timelineMarker}
                    style={{ background: 'var(--success-color)' }}
                  ></div>
                  <div className={styles.timelineContent}>
                    <ActivityCard item={item} />
                  </div>
                </div>
              ))}
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};
