import React from 'react';
import { useNavigate } from 'react-router-dom';
import { Card } from '../../common/Card';
import { Button } from '../../common/Button';
import { Badge } from '../../common/Badge';
import { SLABadge } from '../../common/SLABadge';
import { WorkItem } from '../../../models/Dashboard';
import styles from './MyWorkList.module.css';

export interface MyWorkListProps {
  workItems: WorkItem[];
  title?: string;
  showCount?: boolean;
}

export const MyWorkList: React.FC<MyWorkListProps> = ({
  workItems,
  title = 'Công Việc Ưu Tiên',
  showCount = true,
}) => {
  const navigate = useNavigate();

  const handleRowClick = (item: WorkItem) => {
    if (item.type === 'ticket') {
      navigate(`/tickets/${item.id}`);
    } else {
      navigate(`/tasks/${item.id}`);
    }
  };

  const getPriorityBadge = (priority: string) => {
    switch (priority) {
      case 'emergency':
        return { variant: 'danger' as const, icon: 'fa-exclamation-circle', text: 'Khẩn cấp' };
      case 'high':
        return { variant: 'warning' as const, icon: 'fa-exclamation', text: 'Cao' };
      case 'medium':
        return { variant: 'info' as const, icon: 'fa-minus', text: 'Trung bình' };
      case 'low':
        return { variant: 'success' as const, icon: 'fa-arrow-down', text: 'Thấp' };
      default:
        return { variant: 'secondary' as const, icon: 'fa-minus', text: 'Trung bình' };
    }
  };

  return (
    <Card className={styles.myWorkList}>
      <div className={styles.header}>
        <h3 className={styles.title}>
          <i className="fas fa-fire"></i>{' '}
          {title} {showCount && `(${workItems.length})`}
        </h3>
        <div className={styles.actions}>
          <Button variant="secondary" size="sm">
            <i className="fas fa-filter"></i> Lọc
          </Button>
          <Button variant="secondary" size="sm">
            <i className="fas fa-sort"></i> Sắp xếp
          </Button>
        </div>
      </div>
      <div className={styles.tableContainer}>
        {workItems.length === 0 ? (
          <div className={styles.emptyState}>
            <i className="fas fa-tasks" />
            <p>Không có công việc nào cần xử lý</p>
          </div>
        ) : (
          <table className={styles.table}>
            <thead>
              <tr>
                <th style={{ width: '100px' }}>Mã</th>
                <th>Tiêu đề</th>
                <th style={{ width: '100px' }}>Ưu tiên</th>
                <th style={{ width: '140px' }}>SLA</th>
                <th style={{ width: '120px' }}>Deadline</th>
                <th style={{ width: '100px' }}>Trạng thái</th>
              </tr>
            </thead>
            <tbody>
              {workItems.map((item) => {
                const priorityBadge = getPriorityBadge(item.priority);
                return (
                  <tr
                    key={item.id}
                    className={styles.row}
                    onClick={() => handleRowClick(item)}
                  >
                    <td>
                      <strong>{item.code}</strong>
                    </td>
                    <td>
                      <div className={styles.titleCell}>
                        <div className={styles.itemTitle}>{item.title}</div>
                        <div className={styles.subtitle}>{item.subtitle}</div>
                      </div>
                    </td>
                    <td>
                      <Badge variant={priorityBadge.variant}>
                        <i className={`fas ${priorityBadge.icon}`}></i> {priorityBadge.text}
                      </Badge>
                    </td>
                    <td>
                      <SLABadge status={item.sla.status} timeRemaining={item.sla.remainingTime} />
                    </td>
                    <td>
                      <div
                        className={`${styles.deadline} ${
                          item.deadline.isUrgent ? styles.urgent : ''
                        }`}
                      >
                        <i className="fas fa-clock"></i> {item.deadline.text}
                      </div>
                    </td>
                    <td>
                      <Badge variant={item.status.variant}>{item.status.text}</Badge>
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        )}
      </div>
      <div className={styles.footer}>
        <a href="/tasks" className={styles.viewAllLink}>
          Xem tất cả <i className="fas fa-arrow-right"></i>
        </a>
      </div>
    </Card>
  );
};
