import { apiClient } from '../api';
import type { Ticket } from '../../models/Ticket';
import type { PaginatedResponse } from '../../models/common';
import { unwrap } from '../shared/bffEnvelope';
import type { BffResponse } from '../shared/bffEnvelope';
import type { BffTicketDto, BffPagedResult } from './responseModel';
import { mapBffTicket, mapPagedResult } from './mapper';
import type {
  TicketListQuery,
  CreateTicketRequest,
  UpdateTicketRequest,
  AcceptTicketRequest,
  RejectTicketRequest,
  PendingTicketRequest,
  AssignTicketRequest,
  UpdateProgressRequest,
  UpdateEstimateRequest,
  RequestHelpRequest,
  AssignSupportRequest,
  ResolveTicketRequest,
  CloseTicketRequest,
  ReopenTicketRequest,
} from './requestModel';

/**
 * Real API calls to WebApp BFF ticket endpoints.
 * All routes are relative to VITE_API_URL (web-bff/api/v1).
 *
 * BFF base route: /tickets
 */
export const ticketEndpoint = {
  // ── CRUD ──────────────────────────────────────────────────────────────────

  /** GET /tickets?page&pageSize&... */
  getTickets: async (query: TicketListQuery): Promise<PaginatedResponse<Ticket>> => {
    const params = new URLSearchParams();
    if (query.page)         params.set('page',         String(query.page));
    if (query.pageSize)     params.set('pageSize',     String(query.pageSize));
    if (query.priority)     params.set('priority',     query.priority);
    if (query.status)       params.set('status',       query.status);
    if (query.departmentId) params.set('departmentId', query.departmentId);
    if (query.assigneeId)   params.set('assigneeId',   query.assigneeId);
    if (query.slaStatus)    params.set('slaStatus',    query.slaStatus);
    if (query.search)       params.set('search',       query.search);
    const res = await apiClient.get<BffResponse<BffPagedResult>>(`/tickets?${params}`);
    return mapPagedResult(unwrap(res));
  },

  /** GET /tickets/{id} */
  getTicketById: async (id: string): Promise<Ticket> => {
    const res = await apiClient.get<BffResponse<BffTicketDto>>(`/tickets/${id}`);
    return mapBffTicket(unwrap(res));
  },

  /** POST /tickets */
  createTicket: async (data: CreateTicketRequest): Promise<Ticket> => {
    const res = await apiClient.post<BffResponse<BffTicketDto>>('/tickets', data);
    return mapBffTicket(unwrap(res));
  },

  /** PUT /tickets/{id} */
  updateTicket: async (id: string, data: UpdateTicketRequest): Promise<Ticket> => {
    const res = await apiClient.put<BffResponse<BffTicketDto>>(`/tickets/${id}`, data);
    return mapBffTicket(unwrap(res));
  },

  /** DELETE /tickets/{id} */
  deleteTicket: async (id: string): Promise<void> => {
    await apiClient.delete<BffResponse<object>>(`/tickets/${id}`);
  },

  // ── Assignment ─────────────────────────────────────────────────────────────

  /** PATCH /tickets/{id}/assign */
  assignTicket: async (id: string, req: AssignTicketRequest): Promise<Ticket> => {
    const res = await apiClient.patch<BffResponse<BffTicketDto>>(`/tickets/${id}/assign`, req);
    return mapBffTicket(unwrap(res));
  },

  // ── Triage ─────────────────────────────────────────────────────────────────

  /** PATCH /tickets/{id}/accept */
  acceptTicket: async (id: string, req: AcceptTicketRequest): Promise<Ticket> => {
    const res = await apiClient.patch<BffResponse<BffTicketDto>>(`/tickets/${id}/accept`, req);
    return mapBffTicket(unwrap(res));
  },

  /** PATCH /tickets/{id}/reject */
  rejectTicket: async (id: string, req: RejectTicketRequest): Promise<Ticket> => {
    const res = await apiClient.patch<BffResponse<BffTicketDto>>(`/tickets/${id}/reject`, req);
    return mapBffTicket(unwrap(res));
  },

  /** PATCH /tickets/{id}/pending — request more information */
  pendingTicket: async (id: string, req: PendingTicketRequest): Promise<Ticket> => {
    const res = await apiClient.patch<BffResponse<BffTicketDto>>(`/tickets/${id}/pending`, req);
    return mapBffTicket(unwrap(res));
  },

  // ── Progress & estimate ────────────────────────────────────────────────────

  /** PATCH /tickets/{id}/progress */
  updateProgress: async (id: string, req: UpdateProgressRequest): Promise<Ticket> => {
    const res = await apiClient.patch<BffResponse<BffTicketDto>>(`/tickets/${id}/progress`, req);
    return mapBffTicket(unwrap(res));
  },

  /** PATCH /tickets/{id}/estimate */
  updateEstimate: async (id: string, req: UpdateEstimateRequest): Promise<Ticket> => {
    const res = await apiClient.patch<BffResponse<BffTicketDto>>(`/tickets/${id}/estimate`, req);
    return mapBffTicket(unwrap(res));
  },

  // ── Help workflow ──────────────────────────────────────────────────────────

  /** PATCH /tickets/{id}/request-help */
  requestHelp: async (id: string, req: RequestHelpRequest): Promise<Ticket> => {
    const res = await apiClient.patch<BffResponse<BffTicketDto>>(`/tickets/${id}/request-help`, req);
    return mapBffTicket(unwrap(res));
  },

  /** PATCH /tickets/{id}/assign-support */
  assignSupport: async (id: string, req: AssignSupportRequest): Promise<Ticket> => {
    const res = await apiClient.patch<BffResponse<BffTicketDto>>(`/tickets/${id}/assign-support`, req);
    return mapBffTicket(unwrap(res));
  },

  // ── Resolution ─────────────────────────────────────────────────────────────

  /** PATCH /tickets/{id}/resolve */
  resolveTicket: async (id: string, req: ResolveTicketRequest): Promise<Ticket> => {
    const res = await apiClient.patch<BffResponse<BffTicketDto>>(`/tickets/${id}/resolve`, req);
    return mapBffTicket(unwrap(res));
  },

  /** PATCH /tickets/{id}/close */
  closeTicket: async (id: string, req: CloseTicketRequest): Promise<Ticket> => {
    const res = await apiClient.patch<BffResponse<BffTicketDto>>(`/tickets/${id}/close`, req);
    return mapBffTicket(unwrap(res));
  },

  /** PATCH /tickets/{id}/reopen */
  reopenTicket: async (id: string, req: ReopenTicketRequest): Promise<Ticket> => {
    const res = await apiClient.patch<BffResponse<BffTicketDto>>(`/tickets/${id}/reopen`, req);
    return mapBffTicket(unwrap(res));
  },
};
