/**
 * InstallButton
 *
 * Shown in the Topbar when the app is installable as a PWA.
 * Mirrors the "Open in app" button style from GitHub's browser chrome.
 *
 * States:
 *   installable  — shows button with icon + label "Mở ứng dụng"
 *   not visible  — hidden when already installed or browser doesn't support
 */
import React, { useState, useRef, useEffect } from 'react';
import ReactDOM from 'react-dom';
import styles from './InstallButton.module.css';

export interface InstallButtonProps {
  /** Call to trigger the browser install prompt. */
  onInstall: () => Promise<boolean>;
  /** Pass true when the app is already installed — shows "Mở ứng dụng" instead. */
  isInstalled?: boolean;
  /** Pass true when already running as a standalone PWA — hides the button entirely. */
  isStandalone?: boolean;
  /** Compact mode — icon only, no text label (for mobile Topbar). */
  compact?: boolean;
}

type Platform = 'android' | 'ios' | 'desktop';

function getPlatform(): Platform {
  const ua = navigator.userAgent;
  if (/iPhone|iPad|iPod/.test(ua)) return 'ios';
  if (/Android/.test(ua)) return 'android';
  return 'desktop';
}

export const InstallButton: React.FC<InstallButtonProps> = ({
  onInstall,
  isInstalled = false,
  isStandalone = false,
  compact = false,
}) => {
  const [isLoading, setIsLoading] = useState(false);
  const [justInstalled, setJustInstalled] = useState(false);
  const [showHint, setShowHint] = useState(false);
  const [hintPos, setHintPos] = useState({ top: 0, right: 0 });
  const btnRef = useRef<HTMLButtonElement>(null);
  const platform = getPlatform();

  useEffect(() => {
    if (!showHint || !btnRef.current) return;
    const r = btnRef.current.getBoundingClientRect();
    setHintPos({
      top: r.bottom + 10,
      right: window.innerWidth - r.right,
    });
  }, [showHint]);

  const handleOpenClick = () => {
    if (platform === 'android') {
      // Android Chrome intercepts window.open() for URLs within the installed
      // PWA's scope and launches the standalone app window directly.
      window.open(window.location.origin + '/', '_blank');
      return;
    }
    // iOS and desktop: no JS API — show platform-specific hint
    setShowHint((v) => !v);
  };

  const handleInstallClick = async () => {
    setIsLoading(true);
    try {
      const accepted = await onInstall();
      if (accepted) setJustInstalled(true);
    } finally {
      setIsLoading(false);
    }
  };

  // Already running as PWA — no button needed
  if (isStandalone) return null;

  const showOpen = isInstalled || justInstalled;

  const hint = showHint ? ReactDOM.createPortal(
    <div
      className={styles.openHint}
      role="tooltip"
      style={{ top: hintPos.top, right: hintPos.right }}
    >
      <div className={styles.openHintArrow} />
      {platform === 'ios' ? (
        <>
          <i className={`fas fa-home ${styles.openHintPulse}`} />
          Mở ứng dụng từ <strong>biểu tượng trên màn hình chính</strong>
        </>
      ) : (
        <>
          <i className={`fas fa-arrow-up ${styles.openHintPulse}`} />
          Nhấn <strong>&laquo;&thinsp;Open in app&thinsp;&raquo;</strong> trên thanh địa chỉ
        </>
      )}
      <button className={styles.openHintClose} onClick={() => setShowHint(false)}>&#x2715;</button>
    </div>,
    document.body,
  ) : null;

  if (showOpen) {
    return (
      <>
        <button
          ref={btnRef}
          type="button"
          className={`${styles.installBtn} ${styles.openBtn} ${compact ? styles.compact : ''}`}
          onClick={handleOpenClick}
          aria-label="Mở ứng dụng"
          title="Mở ứng dụng đã cài đặt"
        >
          <i className="fas fa-external-link-alt" />
          {!compact && <span className={styles.label}>Mở ứng dụng</span>}
        </button>
        {hint}
      </>
    );
  }

  return (
    <button
      type="button"
      className={`${styles.installBtn} ${compact ? styles.compact : ''}`}
      onClick={handleInstallClick}
      disabled={isLoading}
      aria-label="Cài đặt ứng dụng"
      title="Cài đặt ứng dụng để mở nhanh hơn"
    >
      <i className={isLoading ? 'fas fa-spinner fa-spin' : 'fas fa-download'} />
      {!compact && (
        <span className={styles.label}>
          {isLoading ? 'Đang cài…' : 'Tải ứng dụng'}
        </span>
      )}
    </button>
  );
};
