import React, { useState } from 'react';
import { Slideout } from '../../../components/common/Slideout';
import { TextArea } from '../../../components/common/TextArea';
import { useAppToast } from '../../../hooks/useAppToast';
import styles from './WorkflowModal.module.css';

interface RequestReassignmentModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSubmit: (reason: string) => Promise<void>;
  taskTitle: string;
}

export const RequestReassignmentModal: React.FC<RequestReassignmentModalProps> = ({
  isOpen,
  onClose,
  onSubmit,
  taskTitle,
}) => {
  const [reason, setReason] = useState('');
  const [submitting, setSubmitting] = useState(false);
  const toast = useAppToast();

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!reason.trim()) return;

    setSubmitting(true);
    try {
      await onSubmit(reason.trim());
      handleClose();
    } catch (error: unknown) {
      toast.fromError(error, 'Đã có lỗi khi gửi yêu cầu, vui lòng thử lại');
    } finally {
      setSubmitting(false);
    }
  };

  const handleClose = () => {
    setReason('');
    onClose();
  };

  const handleConfirmSubmit = () => {
    handleSubmit(new Event('submit') as any);
  };

  return (
    <Slideout 
      isOpen={isOpen} 
      onClose={handleClose} 
      title="Yêu cầu gán lại task"
      width="500px"
      footer={{
        leftLabel: 'Hủy',
        leftAction: handleClose,
        leftDisabled: submitting,
        rightLabel: submitting ? 'Đang gửi...' : 'Gửi yêu cầu',
        rightAction: handleConfirmSubmit,
        rightDisabled: !reason.trim() || submitting,
      }}
    >
      <form onSubmit={handleSubmit} className={styles.form}>
        <div className={styles.taskInfo}>
          <span className={styles.label}>Task:</span>
          <span className={styles.value}>{taskTitle}</span>
        </div>

        <div className={styles.formGroup}>
          <label htmlFor="reason" className={styles.label}>
            Lý do yêu cầu gán lại <span className={styles.required}>*</span>
          </label>
          <TextArea
            id="reason"
            value={reason}
            onChange={(e) => setReason(e.target.value)}
            placeholder="Ví dụ: Tôi không có đủ kiến thức về công nghệ này, cần người có kinh nghiệm hơn..."
            rows={4}
            required
            disabled={submitting}
          />
          <span className={styles.hint}>
            Hãy mô tả rõ lý do để quản lý có thể đưa ra quyết định phù hợp
          </span>
        </div>
      </form>
    </Slideout>
  );
};
